function createSettingsMessagesFromRows(index: 1 | 2 | 3 | 4 | 5): Partial<MessageDictionary> {
  return Object.fromEntries(
    PHASE_1_15_4_LOCALE_ROWS.map((row) => [row[0], row[index]])
  ) as Partial<MessageDictionary>;
}

